INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35911, 'Acts 25:20', 'Acts', 25, 20, 'زه زړه نازړه وم چې څنګه د دې موضوع په هکله څېړنه وکړم، نو د پولوس څخه مې پوښتنه وکړه چې ایا ته غواړې چې اورشلیم ته لاړ شې او هلته دې قضیه وڅېړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_20.mp3', '', 1761754199, 1761754199),
(35912, 'Acts 25:21', 'Acts', 25, 21, 'خو پولوس غوښتنه وکړه تر هغې پورې چې امپراتور د هغه د قضیې په هکله خپله پرېکړه نه وي کړې، هغه دې تر نظارت لاندې وساتل شي. نو ما امر وکړ، ترڅو پورې چې هغه امپراتور ته لېږم هغه دې بندي وساتل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_21.mp3', '', 1761754199, 1761754199),
(35913, 'Acts 25:22', 'Acts', 25, 22, 'اګریپاس فستوس ته وویل: «زه غواړم چې په خپله د دې سړي خبرې واورم.» فستوس ځواب ورکړ: «سبا به د هغه خبرې واورې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_22.mp3', '', 1761754199, 1761754199),
(35914, 'Acts 25:23', 'Acts', 25, 23, 'په بله ورځ اګریپاس او برنیکۍ په زیات شان او شوکت سره راغلل او د قوماندانانو او د ښار د مشرانو سره دربار ته ننوتل. بیا فستوس امر وکړ او پولوس یې حاضر کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_23.mp3', '', 1761754199, 1761754199),
(35915, 'Acts 25:24', 'Acts', 25, 24, 'بیا فستوس وویل: «ای اګریپاس پاچا او ټولو حاضرینو! تاسو دا سړی وینئ چې ټولو یهودیانو که دلته دي او که په اورشلیم کې دي، ورڅخه ماته شکایت کړی دی. هغوی چیغې وهلې چې دا سړی باید ژوندی پاتې نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_24.mp3', '', 1761754199, 1761754199),
(35916, 'Acts 25:25', 'Acts', 25, 25, 'خو زما په نظر هغه کوم داسې کار نه دی کړی چې د مرګ سزا دې ورکړای شي. څرنګه چې هغه خپله عرض وکړ چې امپراتور دې د هغه د قضیې په هکله پرېکړه وکړي، نو ما پرېکړه وکړه چې هغه روم ته ولېږم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_25.mp3', '', 1761754199, 1761754199),
(35917, 'Acts 25:26', 'Acts', 25, 26, 'خو د هغه په هکله زما سره کوم ځانګړی څه شی نشته چې امپراتور ته یې ولیکم. نو هغه مې تاسو ټولو او په ځانګړې توګه ستاسې اګریپاس پاچا حضور ته راوست، ترڅو د هغه د قضیې تر څېړلو وروسته وکولای شم هغه ته یو څه ولیکم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_26.mp3', '', 1761754199, 1761754199),
(35918, 'Acts 25:27', 'Acts', 25, 27, 'ځکه چې زما په نظر دا خبره سمه نه ده چې یو بندي بې له کومو ښکاره تورونو امپراتور ته ولېږم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts25_verse_27.mp3', '', 1761754199, 1761754199),
(35919, 'Acts 12:1', 'Acts', 12, 1, 'په هماغه وخت کې هیرودیس پاچا د کلیسا د ځینو غړو په ځورولو پیل وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_1.mp3', '', 1761754199, 1761754199),
(35920, 'Acts 12:2', 'Acts', 12, 2, 'هغه د یوحنا ورور یعقوب په توره باندې وواژه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_2.mp3', '', 1761754199, 1761754199),
(35921, 'Acts 12:3', 'Acts', 12, 3, 'کله چې هیرودیس ولیدل چې یهودیان په دې کار خوشحاله شول، نو پطروس یې هم ونیوه. دا کار د فطیرې ډوډۍ د اختر په ورځو کې وشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_3.mp3', '', 1761754199, 1761754199),
(35922, 'Acts 12:4', 'Acts', 12, 4, 'کله چې هغه پطروس ونیوه، نو په زندان کې یې واچاوه او هغه یې څلورو ډلګیو ته چې په هر یو کې څلور څلور عسکره وو، وسپاره چې ساتنه یې وکړي. هیرودیس د دې نیت درلود چې د فسحې د اختر څخه وروسته هغه د ټولو خلکو په مخکې محاکمه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_4.mp3', '', 1761754199, 1761754199),
(35923, 'Acts 12:5', 'Acts', 12, 5, 'نو پطروس یې په زندان کې وساته، خو ایماندارانو د زړه له کومي د هغه دپاره خدای ته دعاګانې کولې. پطروس له زندان څخه خلاصیږي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_5.mp3', '', 1761754199, 1761754199),
(35924, 'Acts 12:6', 'Acts', 12, 6, 'یوه شپه مخکې چې هیرودیس غوښتل پطروس د محاکمې دپاره راولي، پطروس د دوو عسکرو په منځ کې په دوو زنځیرونو تړلی ویده پروت ؤ او ساتونکو د زندان په دروازه کې پهره کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_6.mp3', '', 1761754199, 1761754199),
(35925, 'Acts 12:7', 'Acts', 12, 7, 'ناڅاپه د څښتن فرښته راښکاره شوه او په کوټه کې رڼا وځلېدله. فرښتې د پطروس اوږه وخوځوله او هغه یې راویښ کړ او ورته ویې ویل: «زر شه، پاڅېږه.» سمدلاسه د پطروس د لاسونو څخه زنځیرونه ولوېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_7.mp3', '', 1761754199, 1761754199),
(35926, 'Acts 12:8', 'Acts', 12, 8, 'بیا فرښتې هغه ته وویل: «ملا دې وتړه او څپلۍ دې په پښو کړه.» پطروس همداسې وکړل. بیا فرښتې هغه ته وویل: «خپله چپنه دې واغونده او ما پسې راځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_8.mp3', '', 1761754199, 1761754199),
(35927, 'Acts 12:9', 'Acts', 12, 9, 'پطروس راووت او په هغې پسې روان شو. هغه نه پوهېده چې دا هرڅه رښتیا دي، ځکه هغه فکر کاوه چې رویا ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_9.mp3', '', 1761754199, 1761754199),
(35928, 'Acts 12:10', 'Acts', 12, 10, 'هغوی د لومړۍ او دوهمې پوستې څخه تېر شول او د اوسپنې هغې دروازې ته ورسېدل چې د ښار خواته وتلې وه. دروازه په خپله خلاصه شوه او هغوی دباندې راووتل. هغوی په یوه کوڅه کې روان وو او ناڅاپه فرښته د پطروس له سترګو پناه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_10.mp3', '', 1761754199, 1761754199),
(35929, 'Acts 12:11', 'Acts', 12, 11, 'بیا پطروس په هوش راغی او ویې ویل: «اوس پوره باور لرم چې څښتن خپله فرښته راولېږله او زه یې د هیرودیس او له هغه څه نه چې یهودیانو یې تمه درلودله، خلاص کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_11.mp3', '', 1761754199, 1761754199),
(35930, 'Acts 12:12', 'Acts', 12, 12, 'کله چې هغه پوه شو، نو هغه د مریم کور ته لاړ چې د یوحنا مرقوس مور وه. هلته زیات شمېر خلک د دعا دپاره راټول شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_12.mp3', '', 1761754199, 1761754199),
(35931, 'Acts 12:13', 'Acts', 12, 13, 'کله چې پطروس د کور دروازه وټکوله، نو د رودا په نوم یوه وینځه راغله چې دروازه خلاصه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_13.mp3', '', 1761754199, 1761754199),
(35932, 'Acts 12:14', 'Acts', 12, 14, 'هغې د پطروس اواز واورېد او دومره خوشحاله شوه چې د دې په ځای چې دروازه ورته خلاصه کړي، هغې بېرته دننه منډه کړه او هغوی یې خبر کړل چې پطروس دباندې په دروازه کې ولاړ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_14.mp3', '', 1761754199, 1761754199),
(35933, 'Acts 12:15', 'Acts', 12, 15, 'هغوی ورته وویل: «ته لېونۍ شوې یې.» خو هغه په خپله خبره باندې ټینګه ولاړه وه چې همداسې ده. بیا هغوی وویل: «دا به د هغه فرښته وي!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_15.mp3', '', 1761754199, 1761754199),
(35934, 'Acts 12:16', 'Acts', 12, 16, 'خو پطروس په پرله پسې توګه دروازه ټکوله او کله چې هغوی دروازه خلاصه کړه او هغه یې ولیده، نو حیران پاتې شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_16.mp3', '', 1761754199, 1761754199),
(35935, 'Acts 12:17', 'Acts', 12, 17, 'خو پطروس د لاس په اشاره هغوی ته وویل چې غلي شئ او هغوی ته یې دا کیسه وکړه چې څښتن څنګه هغه د زندان څخه راوویست. هغه وویل چې یعقوب او نور ایمانداران له دې څخه خبر کړئ. بیا هغه روان شو او بل ځای ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_17.mp3', '', 1761754199, 1761754199),
(35936, 'Acts 12:18', 'Acts', 12, 18, 'کله چې سهار شو، نو هغه ساتونکي عسکر ډېر وارخطا شول چې په پطروس باندې څه وشول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_18.mp3', '', 1761754199, 1761754199),
(35937, 'Acts 12:19', 'Acts', 12, 19, 'هیرودیس امر وکړ چې پطروس ولټوي، خو هغه یې پیدا نه کړ. هغه د ساتونکو څخه پوښتنې وکړې او د هغوی د اعدام حکم یې ورکړ. له هغې وروسته هیرودیس د یهودیې څخه لاړ او د څه مودې دپاره په قیصریه کې پاتې شو. د هیرودیس مړینه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_19.mp3', '', 1761754199, 1761754199),
(35938, 'Acts 12:20', 'Acts', 12, 20, 'هیرودیس د صور او صیدون په خلکو ډېر په قهر ؤ. هغوی سره راټول شول او هغه ته ورغلل. لومړی هغوی بلاستوس چې د پاچا د ماڼۍ ناظر ؤ، په دې راضي کړ چې د هغوی سره به مرسته وکړي. بیا هغوی د هیرودیس څخه وغوښتل چې روغه جوړه ورسره وکړي، ځکه چې د دوی وطن ته خوراکي شیان د هیرودیس پاچا د وطن څخه راتلل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_20.mp3', '', 1761754199, 1761754199),
(35939, 'Acts 12:21', 'Acts', 12, 21, 'نو په یوې ټاکلې ورځ هیرودیس خپل د پاچاهۍ کالي واغوستل، په تخت باندې کښېناست او هغوی ته یې وینا پیل کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_21.mp3', '', 1761754199, 1761754199),
(35940, 'Acts 12:22', 'Acts', 12, 22, 'خلکو چیغې وهلې: «دا د خدای اواز دی، نه د انسان.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_22.mp3', '', 1761754199, 1761754199),
(35941, 'Acts 12:23', 'Acts', 12, 23, 'سمدلاسه د څښتن فرښتې هیرودیس وواهه، ځکه چې کوم جلال چې باید خدای ته ورکړل شوی وای، هغه خپل ځان ته ورکړ. هغه چینجیو وخوړ او مړ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_23.mp3', '', 1761754199, 1761754199),
(35942, 'Acts 12:24', 'Acts', 12, 24, 'خو په همدې وخت کې د خدای کلام خپرېده او ډېر خلک ایمانداران شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_24.mp3', '', 1761754199, 1761754199),
(35943, 'Acts 12:25', 'Acts', 12, 25, 'نو برناباس او شاوول خپله وظیفه سرته ورسوله او د اورشلیم څخه بېرته انطاکیې ته راستانه شول او د ځان سره یې یوحنا چې بل نوم یې مرقوس ؤ، بوتلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts12_verse_25.mp3', '', 1761754199, 1761754199),
(35944, 'Mark 4:1', 'Mark', 4, 1, 'عیسی یوځل بیا د بحیرې په غاړه تعلیم ورکول پیل کړل. او دومره زیات خلک ورته راټول شوي وو چې هغه ترې کشتۍ ته وخوت او هلته کښېناست او ټول خلک د بحیرې په غاړه ولاړ وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_1.mp3', '', 1761754199, 1761754199),
(35945, 'Mark 4:2', 'Mark', 4, 2, 'هغه هغوی ته په مثالونو کې ډېر شیان ورزده کول. کله چې هغه تعلیم ورکاوه، نو هغوی ته یې وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_2.mp3', '', 1761754199, 1761754199),
(35946, 'Mark 4:3', 'Mark', 4, 3, '«واورئ، په یو وخت کې یو بزګر د تخم شیندلو دپاره خپل پټي ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_3.mp3', '', 1761754199, 1761754199),
(35947, 'Mark 4:4', 'Mark', 4, 4, 'کله چې هغه تخم شینده، نو یو څه تخم په لاره کې ولوېد. بیا مرغان راغلل او هغه یې وخوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_4.mp3', '', 1761754199, 1761754199),
(35948, 'Mark 4:5', 'Mark', 4, 5, 'څه تخم په داسې ځمکه کې ولوېد چې تیږې یې لرلې، نو هغه تخم زر راشین شو، ځکه چې خاوره یې کمه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_5.mp3', '', 1761754199, 1761754199),
(35949, 'Mark 4:6', 'Mark', 4, 6, 'خو کله چې لمر راوخوت، نو هغه بوټي وسوځېدل او وچ شول، ځکه چې ریښې یې ژورې نه وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_6.mp3', '', 1761754199, 1761754199),
(35950, 'Mark 4:7', 'Mark', 4, 7, 'څه تخم په اغزو کې ولوېد او کله چې اغزي لوی شول، نو بوټي یې لاندې کړل او حاصل یې ورنه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_7.mp3', '', 1761754199, 1761754199),
(35951, 'Mark 4:8', 'Mark', 4, 8, 'نور تخم په حاصلخیزه خاوره کې ولوېد او هغه راشین شو، لوی شو، حاصل یې ورکړ او دېرش چنده، شپېته چنده او سل چنده حاصل یې ورکړ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_8.mp3', '', 1761754199, 1761754199),
(35952, 'Mark 4:9', 'Mark', 4, 9, 'بیا عیسی وویل: «که څوک غوږونه لري، نو هغه دې واوري.» د مثالونو مقصد (متي ۱۳‏:‌۱۰‌‏-‌۱۷ او لوقا ۸‏:‌۹‌‏-‌۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark4_verse_9.mp3', '', 1761754199, 1761754199),
