(35997, 'Luke 16:13', 'Luke', 16, 13, 'هېڅ غلام نه شي کولای چې د دوو بادارانو خدمت وکړي، ځکه چې داسې غلام به د یو څخه کرکه کوي او د بل سره به مینه او یا دا چې یو ته به وفادار وي او بل ته به په سپکه سترګه ګوري. تاسو نه شئ کولای چې هم د خدای بندګي وکړئ او هم د پیسو بندګي وکړئ.» شریعت او د خدای پاچاهي (متي ۱۱‏:‌۱۲‌‏-‌۱۳، ۵‏:‌۳۱‌‏-‌۳۲ او مرقوس ۱۰‏:‌۱۱‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_13.mp3', '', 1761754199, 1761754199),
(35998, 'Luke 16:14', 'Luke', 16, 14, 'فریسیانو چې دا خبرې واورېدلې نو په عیسی باندې یې ملنډې ووهلې، ځکه چې هغوی د پیسو سره مینه لرله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_14.mp3', '', 1761754199, 1761754199),
(35999, 'Luke 16:15', 'Luke', 16, 15, 'عیسی هغوی ته وویل: «تاسو داسې خلک یئ چې خپل ځانونه د نورو په مخکې عادلان ښکاره کوئ، خو خدای ستاسو زړونه ښه پېژني. ځکه کوم شیان چې د انسانانو په نظر کې ډېر ارزښت لري، خدای هغه بد ګڼي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_15.mp3', '', 1761754199, 1761754199),
(36000, 'Luke 16:16', 'Luke', 16, 16, 'د یحیی تر راتللو پورې خلکو د تورات او د پیغمبرانو په لیکنو عمل کاوه. له هغې وروسته د خدای د پاچاهۍ زېری خپور شو او هرڅوک زیات کوښښ کوي چې هغې ته وردننه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_16.mp3', '', 1761754199, 1761754199),
(36001, 'Luke 16:17', 'Luke', 16, 17, 'د ځمکې او اسمان له منځه تلل اسانه دي، له دې نه چې د شریعت یو ټکی هم له منځه لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_17.mp3', '', 1761754199, 1761754199),
(36002, 'Luke 16:18', 'Luke', 16, 18, 'هرڅوک چې خپله ښځه طلاقه کړي او د بلې ښځې سره واده وکړي، نو هغه زنا کوي او هرڅوک چې د طلاقې شوې ښځې سره واده وکړي، هغه هم زنا کوي.» د شتمن سړي او ایلعازر مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_18.mp3', '', 1761754199, 1761754199),
(36003, 'Luke 16:19', 'Luke', 16, 19, 'عیسی وویل: «یو شتمن سړی ؤ چې هره ورځ به یې تر ټولو قیمتي کالي اغوستل او په عیش او عشرت کې یې ژوند تېراوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_19.mp3', '', 1761754199, 1761754199),
(36004, 'Luke 16:20', 'Luke', 16, 20, 'د هغه د دروازې په مخکې به یو سوالګر چې ایلعازر نومېده او بدن یې له ټپونو څخه ډک ؤ، پروت ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_20.mp3', '', 1761754199, 1761754199),
(36005, 'Luke 16:21', 'Luke', 16, 21, 'او په دې تمه به ؤ چې د هغه شتمن سړي د دسترخوان څخه په پاتې شویو ټوټو باندې ځان موړ کړي. حتی سپي به راتلل او د هغه ټپونه به یې څټل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_21.mp3', '', 1761754199, 1761754199),
(36006, 'Luke 16:22', 'Luke', 16, 22, 'داسې وشول چې هغه غریب سړی مړ شو او فرښتو هغه د ابراهیم څنګ ته یووړ. بیا هغه شتمن سړی هم مړ شو او خاورو ته وسپارل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_22.mp3', '', 1761754199, 1761754199),
(36007, 'Luke 16:23', 'Luke', 16, 23, 'هغه د مړو دنیا ته لاړ او هلته ډېر په عذاب ؤ. هغه چې پورته وکتل د لېرې نه یې ابراهیم ولیده چې ایلعازر یې په خوا کې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_23.mp3', '', 1761754199, 1761754199),
(36008, 'Luke 16:24', 'Luke', 16, 24, 'بیا هغه چیغې کړې او ویې ویل: ‹ای زما نیکه ابراهیمه! په ما رحم وکړه او ایلعازر راولېږه چې خپله ګوته په اوبو کې لمده کړي او زما ژبه پرې یخه کړي، ځکه چې زه په دې اور کې ډېر په عذاب یم.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_24.mp3', '', 1761754199, 1761754199),
(36009, 'Luke 16:25', 'Luke', 16, 25, 'خو ابراهیم وویل: ‹زویه! در په یاد کړه، تا په خپل ژوند کې ټول ښه شیان تر‌لاسه کړل او ټول بد شیان د ایلعازر په نصیب کې وو. خو اوس هغه دلته ارام دی او ته په عذاب کې یې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_25.mp3', '', 1761754199, 1761754199),
(36010, 'Luke 16:26', 'Luke', 16, 26, 'برسېره پر‌دې، زمونږ او ستاسو په منځ کې یوه لویه کنده شته چې له هغې څخه نه څوک درپورې وتلی شي او نه څوک ترې راپورې وتلی شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke16_verse_26.mp3', '', 1761754199, 1761754199);